function openWizard(){D.wizard=wizardDefaults();D.wizardStep=0;wizardRender();}
window.dcxOpenWizard=openWizard;window.dcxWizardChanged=formChanged;window.dcxWizardBack=function(){wizardSave();D.wizardStep=Math.max(0,D.wizardStep-1);wizardRender();};window.dcxWizardNext=function(){wizardSave();if(D.wizardStep===1&&!D.wizard.title)return notify('Document title is required',false);D.wizardStep=Math.min(8,D.wizardStep+1);wizardRender();};

