window.dcxCreateRevision=async function(docId){var d=byId(D.data.documents,docId),old=currentRevision(docId),summary=prompt('Describe the controlled change for the new revision:');if(!summary)return;var oldV=version(old||d),parts=oldV.split('.'),major=parseInt(parts[0])||1,minor=parseInt(parts[1])||0,increment=configValue('Revision & Versioning','default_increment','minor'),newV=increment==='major'?(major+1)+'.0':major+'.'+(minor+1),body={company_id:company(),document_id:String(docId),revision_code:newV,status:'draft',language_code:old?.language_code||d.language_code||'en',scope_type:old?.scope_type||d.scope_type||'company',scope_id:old?.scope_id||d.scope_id||null,title:title(d),change_summary:summary,content_json:old?.content_json||{description:d.description,scope:d.scope},metadata_json:old?.metadata_json||{document_type:type(d),owner:d.owner||d.doc_owner},source_revision_id:old?.id||null,created_by:uid()};try{body.content_hash=await hashText(JSON.stringify(body.content_json));var r=await persist(REVISIONS,body);D.data.revisions.unshift(r);try{await persist('documents',{current_revision_id:r.id,lifecycle_state:'under_revision',version:newV,doc_version:newV,updated_at:new Date().toISOString()},docId);Object.assign(d,{current_revision_id:r.id,lifecycle_state:'under_revision',version:newV,doc_version:newV});}catch(_){}await audit('revision',r.id,'created',old,r,summary,docId,r.id);D.docTab='revisions';render();notify('Draft revision '+newV+' created');}catch(e){D.schemaReady=false;notify('Revision not created: run the database upgrade and retry.',false);}};

